/* SPEC-SUIYIN-ADMIN-050@1.0.0 — local navigation snapshot. */
'use strict';
const $=id=>document.getElementById(id);
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const params=new URLSearchParams(location.search);
const navStorageKey=id=>(params.get('qa')==='1'?'admin-qa-nav:':'admin-nav-override:')+id;
let data,tenant,leaves=[],tabs=[],active,expanded=new Set();
const legacyPages={sales:'销售管理','expert-info':'专家信息','friend-list':'好友列表','group-list':'群列表','friend-add':'添加好友','friend-review':'删退审核','friend-tag':'好友标签',script:'话术管理',product:'商品管理',massmsg:'群发管理',pyq:'PYQ管理','reward-detail':'分佣明细','reward-total':'分佣合计','reward-topup':'充值确认','reward-prepay':'预付确认','reward-income':'收入确认','stats-referral':'拉新记录','stats-sales':'销售统计','stats-rank':'销售排名','stats-revisit':'回访统计','stats-shift':'上班记录','stats-msgratio':'消息占比统计','stats-viewlog':'数据查看日志','stats-retention':'留存统计','stats-mass':'群发统计','stats-pyq':'朋友圈统计','stats-saleuse':'销售使用统计','stats-script':'话术统计','stats-ai-assist':'AI辅助统计','stats-invite':'群邀请提及率','chat-all':'全部聊天','chat-assign':'分配记录','chat-saleban':'销售词控','chat-cusban':'客户词控','chat-ai-analysis':'智能分析','wechat-account':'帐号状态','wechat-acquire':'拉新文案','wechat-buddy':'通友管理','ai-prompt':'AI提示词库','ai-model':'AI模型管理','sys-role':'角色管理','sys-menu':'菜单管理','sys-tagtpl':'标签模板管理','sys-config':'系统设置'};
function icon(markup){const span=el('span','nav-icon');if(markup){const svg=new DOMParser().parseFromString(markup,'image/svg+xml').documentElement;if(svg.tagName==='svg'&&!svg.querySelector('script,foreignObject,image,use')&&![...svg.querySelectorAll('*'),svg].some(n=>[...n.attributes].some(a=>/^on|href/i.test(a.name)))){svg.setAttribute('aria-hidden','true');span.append(document.importNode(svg,true));}}return span;}
function state(title,detail,retry){const box=el('section','shell-state');box.append(el('h2','',title),el('p','',detail));if(retry){const b=el('button','primary','重新载入');b.onclick=()=>location.reload();box.append(b);}return box;}
function closeUser(){ $('userPanel').hidden=true;$('userTrigger').setAttribute('aria-expanded','false'); }
function toggleUser(){const opening=$('userPanel').hidden;$('userPanel').hidden=!opening;$('userTrigger').setAttribute('aria-expanded',String(opening));if(opening){$('tenantSearch').value='';renderTenants();$('tenantSearch').focus();}}
function renderTenants(){const needle=$('tenantSearch').value.trim().toLowerCase();const list=$('tenantList');list.replaceChildren();const selected=data.tenants.filter(t=>[t.name,t.brand,t.domain,t.id].join(' ').toLowerCase().includes(needle));selected.forEach(t=>{const li=el('li'),b=el('button','tenant-choice');b.append(el('span','',t.name));b.disabled=t.id===tenant?.id;b.setAttribute('aria-label',t.name+(b.disabled?'，当前企业':''));b.append(el('small','',b.disabled?'当前企业':'↗'));b.onclick=()=>switchTenant(t);li.append(b);list.append(li)});if(!selected.length)list.append(el('li','no-match','没有找到企业'));}
function switchTenant(target){const url=new URL(location.href);url.search='';url.searchParams.set('tenant',target.id);const targetLeaves=target.menu.flatMap(g=>g.children||[g]);url.searchParams.set('page',targetLeaves.some(l=>l.route===active)?active:targetLeaves[0].route);const win=window.open(url.href,'_blank');if(win){win.opener=null;$('popupFallback').hidden=true;closeUser();}else{const box=$('popupFallback');box.replaceChildren(document.createTextNode('浏览器未打开新页签。'));const link=el('a','','点击打开 '+target.name);link.href=url.href;link.target='_blank';link.rel='noopener';const close=el('button','','×');close.setAttribute('aria-label','关闭提示');close.onclick=()=>box.hidden=true;box.append(link,close);box.hidden=false;}}
function renderNav(){const list=el('ul');tenant.menu.forEach(g=>{const li=el('li');if(g.children){const d=el('details','nav-group');d.dataset.group=g.id;d.open=expanded.has(g.id);const s=el('summary');s.append(icon(window.AdminLiveUI?.menuIcons[g.label]||g.icon),el('span','',g.label));d.append(s);const children=el('ul');g.children.forEach(c=>{const row=el('li');row.append(navButton(c));children.append(row)});d.append(children);d.addEventListener('toggle',()=>d.open?expanded.add(g.id):expanded.delete(g.id));li.append(d);}else li.append(navButton(g));list.append(li)});$('navigation').replaceChildren(list);}
function navButton(item){const b=el('button','nav-button'+(item.route===active?' active':''));b.dataset.route=item.route;b.title=item.platformLabel;b.append(icon(window.AdminLiveUI?.menuIcons[item.label]||item.icon),el('span','',item.label));if(item.route===active)b.setAttribute('aria-current','page');b.onclick=()=>{openPage(item.route);document.body.classList.remove('nav-mobile-open');};return b;}
function pageLabel(item){return leaves.filter(l=>l.label===item.label).length>1?item.platformLabel:item.label;}
function save(){try{sessionStorage.setItem('admin-nav:'+tenant.id,JSON.stringify(tabs));}catch{}}
function renderTabs(){const bar=$('tabs');bar.replaceChildren();tabs.forEach(route=>{const item=leaves.find(l=>l.route===route),wrap=el('div','tab'+(route===active?' selected':'')),b=el('button');b.id='tab-'+route;b.setAttribute('role','tab');b.setAttribute('aria-selected',String(route===active));b.setAttribute('aria-controls','panel-'+route);b.tabIndex=route===active?0:-1;b.title=item.platformLabel;b.append(icon(window.AdminLiveUI?.menuIcons[item.label]||item.icon),el('span','',pageLabel(item)));b.onclick=()=>openPage(route);b.onkeydown=e=>{const i=tabs.indexOf(route);let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();openPage(tabs[next]);$('tab-'+tabs[next]).focus();}if(e.key==='Delete'){e.preventDefault();closePage(route);$('tab-'+active)?.focus();}};wrap.append(b);{const c=el('button','close-tab','×');c.setAttribute('aria-label','关闭 '+pageLabel(item));c.onclick=()=>closePage(route);wrap.append(c);}bar.append(wrap)});$('tab-'+active)?.scrollIntoView({block:'nearest',inline:'nearest'});}
function closePage(route){const i=tabs.indexOf(route);tabs=tabs.filter(x=>x!==route);$('panel-'+route)?.remove();if(active===route)active=tabs[Math.min(i,tabs.length-1)];save();if(!tabs.length){active=null;renderTabs();$('navigation').querySelectorAll('.active').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});const url=new URL(location.href);url.searchParams.delete('page');history.replaceState(null,'',url);return;}openPage(active);}
function makeFrame(item){const wrap=el('section','frame-wrap');wrap.id='panel-'+item.route;wrap.setAttribute('role','tabpanel');wrap.setAttribute('aria-labelledby','tab-'+item.route);const frame=el('iframe','page-frame');frame.title=tenant.name+' · '+pageLabel(item);const p=new URLSearchParams({tenant:tenant.id,route:item.route,tenantName:tenant.name,pageName:pageLabel(item),capturedAt:tenant.capturedAt,status:item.contentStatus});if(params.get('qa')==='1')p.set('qa','1');frame.src='admin-content.html?'+p;const fail=()=>{wrap.replaceChildren(state('页面读取失败','请重新加载本地页面。'));const b=el('button','primary','重试');b.onclick=()=>wrap.replaceWith(makeFrame(item));wrap.firstChild.append(b);};frame.onerror=fail;frame.onload=()=>{try{if(!frame.contentDocument?.querySelector('#app,.filter-bar'))fail();}catch{fail();}};wrap.append(frame);return wrap;}
function openPage(route){const item=leaves.find(l=>l.route===route);if(!item){$('pages').replaceChildren(state('本租户没有这个页面入口','请从左侧菜单选择要查看的页面。'));active=null;renderTabs();return;}active=route;if(!tabs.includes(route))tabs.push(route);tenant.menu.forEach(g=>{if(g.children?.some(c=>c.route===route)){expanded.add(g.id);const details=$('navigation').querySelector('[data-group="'+g.id+'"]');if(details)details.open=true;}});$('pages').querySelector('.shell-state')?.remove();if(!$('panel-'+route))$('pages').append(makeFrame(item));$('pages').querySelectorAll('.frame-wrap').forEach(w=>w.hidden=w.id!=='panel-'+route);$('navigation').querySelectorAll('.nav-button').forEach(b=>{b.classList.toggle('active',b.dataset.route===route);if(b.dataset.route===route)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const url=new URL(location.href);url.searchParams.set('tenant',tenant.id);url.searchParams.set('page',route);history.replaceState(null,'',url);renderTabs();save();}
function applyLocalMenu(){let override;try{override=JSON.parse(localStorage.getItem(navStorageKey(tenant.id))||'null');}catch{}tenant.menu=window.AdminMenuState.visible(tenant,override);}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='admin-navigation-updated'&&e.data.tenant===tenant?.id)location.reload();});
window.addEventListener('storage',e=>{if(e.key===navStorageKey(tenant?.id))location.reload();});
async function init(){try{const response=await fetch('data/navigation-snapshot.json');if(!response.ok)throw new Error('snapshot unavailable');data=await response.json();if(!Array.isArray(data.tenants)||!data.tenants.length)throw new Error('invalid snapshot');const requested=params.get('tenant')||'yestar-sz';tenant=data.tenants.find(t=>t.id===(data.aliases[requested]||requested));$('userTrigger').disabled=false;renderTenants();if(!tenant){$('brandName').textContent='管理后台';$('pages').replaceChildren(state('此企业不在本次对照范围','请通过右上角企业列表选择已保留的企业。'));return;}$('brandName').textContent=tenant.brand;if(tenant.clientVersion)document.querySelector('.client-note small').textContent=tenant.clientVersion;$('brandLogo').hidden=!tenant.brand;document.title=(tenant.brand||tenant.name)+' · 管理后台原型';applyLocalMenu();leaves=tenant.menu.flatMap(g=>g.children||[g]);let route=params.get('page')||(tenant.id==='yestar-sz'?'wechatStatus':leaves[0].route);if(legacyPages[route])route=leaves.find(l=>l.label===legacyPages[route])?.route||route;try{tabs=JSON.parse(sessionStorage.getItem('admin-nav:'+tenant.id)||'[]').filter((r,i,a)=>a.indexOf(r)===i&&leaves.some(l=>l.route===r));}catch{tabs=[];}renderNav();$('pages').replaceChildren();tabs.forEach(r=>$('pages').append(makeFrame(leaves.find(l=>l.route===r))));openPage(leaves.some(l=>l.route===route)?route:leaves[0].route);}catch(error){$('pages').replaceChildren(state('导航读取失败','请确认本地预览服务已启动，然后重新载入。',true));}}
function syncSidebar(){const small=matchMedia('(max-width:760px)').matches;const shown=small?document.body.classList.contains('nav-mobile-open'):!document.body.classList.contains('nav-collapsed');document.querySelector('.sidebar').inert=!shown;$('collapse').setAttribute('aria-expanded',String(shown));}
new MutationObserver(syncSidebar).observe(document.body,{attributes:true,attributeFilter:['class']});window.addEventListener('resize',syncSidebar);syncSidebar();
$('userTrigger').onclick=toggleUser;$('tenantSearch').oninput=renderTenants;$('collapse').onclick=()=>{const small=matchMedia('(max-width:760px)').matches;document.body.classList.toggle(small?'nav-mobile-open':'nav-collapsed');$('collapse').setAttribute('aria-expanded',String(small?document.body.classList.contains('nav-mobile-open'):!document.body.classList.contains('nav-collapsed')));};$('scrim').onclick=()=>document.body.classList.remove('nav-mobile-open');$('closeOthers').onclick=()=>{if(!active)return;tabs.filter(r=>r!==active).forEach(r=>$('panel-'+r)?.remove());tabs=[active];save();renderTabs();};document.addEventListener('click',e=>{if(!$('userPanel').contains(e.target)&&!$('userTrigger').contains(e.target))closeUser();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('userPanel').hidden){closeUser();$('userTrigger').focus();}document.body.classList.remove('nav-mobile-open');}});init();

const sourceHeaderIcons=window.AdminLiveUI?.headerIcons||[];if(sourceHeaderIcons[0])$('collapse').innerHTML=sourceHeaderIcons[0];if(sourceHeaderIcons[1])document.querySelector('.chevron').innerHTML=sourceHeaderIcons.at(-1);window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='admin-dialog-state')document.body.classList.toggle('has-dialog',e.data.open);});$('dialogScrim').onclick=()=>document.querySelector('.frame-wrap:not([hidden]) iframe')?.contentWindow.postMessage({type:'admin-dialog-close'},location.origin);
